<script>
    /* --- Core Utility Functions (DO NOT MODIFY) --- */
    function SafeGetValue(obj, path, defaultValue = "N/A") {
        let keys = Array.isArray(path) ? path : path.split('.');
        let current = obj;
        for (let i = 0; i < keys.length; i++) {
            if (current === undefined || current === null || typeof current !== 'object' || !current.hasOwnProperty(keys[i])) {
                return defaultValue;
            }
            current = current[keys[i]];
        }
        if (current === undefined || current === null) {
            return defaultValue;
        }
        if (Array.isArray(current)) {
            if (current.length > 0) {
                 const actualValue = current[0];
                 if (typeof actualValue === 'boolean') {
                     return actualValue;
                 }
                 return String(actualValue);
            } else {
                return defaultValue;
            }
        }
        if (typeof current === 'boolean') {
            return current;
        }
        return String(current);
    }

    function updateProgressBar(barId, valueMainId, valueDescId, rawValueFromCharacterData, min, max, colorClass) {
        const progressBar = document.getElementById(barId);
        const valueMainDisplay = document.getElementById(valueMainId);
        const valueDescDisplay = document.getElementById(valueDescId);

        if (!valueMainDisplay) { return; }

        let fullDisplayString = Array.isArray(rawValueFromCharacterData) ? String(rawValueFromCharacterData[0]) : String(rawValueFromCharacterData);
        let descriptionText = Array.isArray(rawValueFromCharacterData) && rawValueFromCharacterData.length > 1 ? String(rawValueFromCharacterData[1]) : "";
        let numericValue = min;

        const parenDescMatch = String(fullDisplayString).match(/\((.+)\)$/);
        if (parenDescMatch && parenDescMatch[1]) {
            descriptionText = parenDescMatch[1];
            fullDisplayString = String(fullDisplayString).substring(0, parenDescMatch.index).trim();
        }

        const valueMatch = String(fullDisplayString).match(/(-?\d+(\.\d+)?)(?=[^\d.]*$|->)/);
         if (valueMatch) {
            numericValue = parseFloat(valueMatch[1]);
            const parts = String(fullDisplayString).split('->');
            valueMainDisplay.innerText = parts.length > 1 ? parts[parts.length - 1].trim() : parts[0].trim();
         } else if (!isNaN(parseFloat(fullDisplayString))) {
             numericValue = parseFloat(fullDisplayString);
             valueMainDisplay.innerText = fullDisplayString;
         } else {
             if (Array.isArray(rawValueFromCharacterData) && typeof rawValueFromCharacterData[0] === 'number') {
                 numericValue = rawValueFromCharacterData[0];
                 valueMainDisplay.innerText = String(numericValue);
             } else if (typeof rawValueFromCharacterData === 'number' || typeof rawValueFromCharacterData === 'string') {
                 valueMainDisplay.innerText = String(rawValueFromCharacterData);
             } else {
                 valueMainDisplay.innerText = SafeGetValue({ temp: rawValueFromCharacterData }, 'temp', String(min));
             }
         }

        if (valueDescDisplay) {
            valueDescDisplay.innerText = descriptionText ? `(${descriptionText})` : "";
        }

        if (progressBar) {
            /* Handle case where max is 0 or less to prevent division by zero and ensure visualization */
            const effectiveMax = max <= min ? min + 1 : max; // Ensure a valid range if max isn't greater than min
            const clampedValue = Math.max(min, Math.min(effectiveMax, numericValue));
            const range = effectiveMax - min;
            const percentage = range === 0 ? (clampedValue >= effectiveMax ? 100 : 0) : ((clampedValue - min) / range) * 100;

            progressBar.style.width = `${Math.max(0, Math.min(100, percentage))}%`;
            progressBar.className = 'progress-bar-value ' + (colorClass || '');
        }
    }

    function toggleSection(element) {
        const content = element.nextElementSibling;
        const arrow = element.querySelector('span:last-child');
        if (!content || !arrow) return;
        const isExpanded = content.classList.toggle('expanded');
        element.classList.toggle('expanded-header', isExpanded);
        arrow.innerText = isExpanded ? '▲' : '▼';
    }
    /* --- End of Core Utility Functions --- */

    /* --- Helper Functions --- */
    function getWeatherIcon(weatherString) {
         switch(weatherString) {
             case '晴朗': return '☀️'; case '多云': return '☁️'; case '阴天': return '🌥️';
             case '小雨': return '🌦️'; case '大雨': return '🌧️'; case '雷暴': return '⛈️';
             case '有雾': return '🌫️'; case '小雪': return '🌨️'; default: return '❓';
         }
    }

    function setOpinionClass(element, opinionValue) {
         element.classList.remove('status-opinion-positive', 'status-opinion-neutral', 'status-opinion-controversial', 'status-opinion-negative', 'status-opinion-hot');
         switch(opinionValue) {
             case '正面': element.classList.add('status-opinion-positive'); break;
             case '有利': element.classList.add('status-opinion-positive'); break; /* Added '有利' alias */
             case '中立': element.classList.add('status-opinion-neutral'); break;
             case '有争议': element.classList.add('status-opinion-controversial'); break;
             case '负面': element.classList.add('status-opinion-negative'); break;
             case '不利': element.classList.add('status-opinion-negative'); break; /* Added '不利' alias */
