                  reiFields.forEach(id => { const el = document.getElementById(id); if (el) el.innerText = 'N/A'; });
                  const reiBars = ['rei-affection-user-bar', 'rei-shy-bar', 'rei-lust-bar', 'rei-fans-bar'];
                  reiBars.forEach(id => { const bar = document.getElementById(id); if(bar) bar.style.width='0%'; });
             }


            /* Default Expansion: Expand World and Mashiro sections */
             const headers = document.querySelectorAll('.section-header');
             if (headers.length > 0) toggleSection(headers[0]); // Expand World Status
             if (headers.length > 2) toggleSection(headers[2]); // Expand Mashiro Status (assuming order: World, User, Mashiro, Rei)


        } catch (error) {
            document.getElementById('status-card').innerHTML = `<p style='color:red; padding:10px;'>💔 状态栏加载出错: ${error.message}</p>`;
            console.error("Error initializing status display:", error);
        }
    }

    /* Initialize display when the DOM is ready */
    document.addEventListener('DOMContentLoaded', initDisplay);
</script>
